function addMessage(m){let row=document.createElement('div');row.className='message';row.dataset.testid='message';row.dataset.id=m.id;row.innerHTML='<span class="message-avatar">'+(m.author.display_name||m.author.username)[0]+'</span><span class="message-author">'+m.author.username+'</span><span class="message-time">'+new Date(m.created_at).toLocaleString()+'</span><div class="message-body">'+esc(m.body)+'</div><span class="reply-count">'+(m.reply_count?m.reply_count+' repl'+(m.reply_count==1?'y':'ies'):'')+'</span><div class="toolbar"><button class="edit-message-btn">Edit</button><button class="delete-message-btn">Delete</button><button class="open-thread-btn">Thread</button><button class="reaction-button">😀</button></div><div class="reactions"></div>';row.querySelector('.edit-message-btn').onclick=()=>editRow(row,m);row.querySelector('.delete-message-btn').onclick=async()=>{await api('/messages/'+m.id,{method:'DELETE'});row.remove()};row.querySelector('.open-thread-btn').onclick=()=>openThread(m);row.querySelector('.reaction-button').onclick=()=>picker(row,m);$('message-list').append(row)}
function esc(s){return s.replace(/[&<>"]/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[x]))}
function editRow(row,m){let b=row.querySelector('.message-body'),i=document.createElement('input');i.className='edit-message-input';i.value=m.body;b.replaceWith(i);i.focus();i.onkeydown=async e=>{if(e.key==='Enter'){let j=await api('/messages/'+m.id,{method:'PATCH',body:JSON.stringify({body:i.value})});m=j.message;row.querySelector('.message-body')?.remove();let n=document.createElement('div');n.className='message-body';n.textContent=m.body;i.replaceWith(n);let z=document.createElement('span');z.className='message-edited';z.textContent=' edited';row.querySelector('.message-time').after(z)}}}
async function picker(row,m){let p=document.createElement('div');p.className='picker';p.dataset.testid='emoji-picker';['😀','👍','❤️','🎉','😂','🚀','🔥','👏'].forEach(e=>{let b=document.createElement('button');b.dataset.testid='emoji-option';b.textContent=e;b.onclick=async()=>{let j=await api('/messages/'+m.id+'/reactions',{method:'POST',body:JSON.stringify({emoji:e})});p.remove();row.querySelector('.reactions').innerHTML='<span class="reaction-chip">'+e+' '+j.reactions.find(x=>x.emoji===e).count+'</span>'};p.append(b)});row.append(p)}
$('composer').onsubmit=async e=>{e.preventDefault();let i=$('message-input');if(!i.value.trim())return;let j=await api('/channels/'+current.id+'/messages',{method:'POST',body:JSON.stringify({body:i.value})});messages.unshift(j.message);i.value='';renderMessages()};
async function openThread(m){$('thread-panel').classList.remove('hidden');$('thread-list').innerHTML='';$('thread-panel').dataset.parent=m.id;let j=await api('/messages/'+m.id+'/replies');j.replies.forEach(x=>{let d=document.createElement('div');d.textContent=x.author.username+': '+x.body;$('thread-list').append(d)})}
$('thread-form').onsubmit=async e=>{e.preventDefault();let i=$('thread-input'),m=await api('/channels/'+current.id+'/messages',{method:'POST',body:JSON.stringify({body:i.value,parent_id:+$('thread-panel').dataset.parent})});let d=document.createElement('div');d.textContent=me.username+': '+m.message.body;$('thread-list').append(d);i.value='';let p=document.querySelector('[data-id="'+$('thread-panel').dataset.parent+'"] .reply-count');if(p)p.textContent='1 reply'};
$('close-thread').onclick=()=>$('thread-panel').classList.add('hidden');$('logout-btn').onclick=()=>{localStorage.removeItem('huddle.token');token=null;showAuth()};$('new-channel-btn').onclick=()=>$('create-channel-modal').classList.remove('hidden');$('create-channel-cancel').onclick=()=>$('create-channel-modal').classList.add('hidden');
$('create-channel-form').onsubmit=async e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e.target));try{let j=await api('/workspaces/'+workspace.slug+'/channels',{method:'POST',body:JSON.stringify({name:d.name,is_private:$('create-channel-private').checked})});$('create-channel-modal').classList.add('hidden');await renderWorkspace();selectChannel(j.channel)}catch(x){$('create-channel-error').textContent=x.message}};
if(token)api('/auth/me').then(j=>{me=j.user;showApp()}).catch(showAuth);else showAuth();
</script></body></html>
EOF
